class Solution:
    def merge(self, intervals: List[List[int]]) -> List[List[int]]:
        intervals.sort()                # 默认先按起点排
        res = []
        for a, b in intervals:
            if res and a <= res[-1][1]:
                res[-1][1] = max(res[-1][1], b)   # 重叠，延长终点
            else:
                res.append([a, b])                # 不重叠，另起一段
        return res

